    public static final String[] ATTRIBUTES = new String[] {
        SdkConstants.ATTR_LAYOUT_ALIGN_PARENT_LEFT, SdkConstants.ATTR_LAYOUT_ALIGN_PARENT_START,
        SdkConstants.ATTR_LAYOUT_ALIGN_PARENT_RIGHT, SdkConstants.ATTR_LAYOUT_ALIGN_PARENT_END,
        ...
    };

    @Override
    public Collection<String> getApplicableAttributes() {
        return Arrays.asList(ATTRIBUTES);
    }

    @Override
    public boolean appliesTo(ResourceFolderType folderType) {
        return folderType == ResourceFolderType.LAYOUT || folderType == ResourceFolderType.DRAWABLE;
    }

    @Override
    public void visitAttribute(XmlContext context, Attr attribute) {
        String name = attribute.getLocalName();
        if (!isRtlAttributeName(name)) {
            return;
        }
        if (SdkConstants.ANDROID_URI.equals(attribute.getNamespaceURI())) {
            checkRtlCompat(context, attribute, name);
        }
    }

    private void checkRtlCompat(XmlContext context, Attr attribute, String name) {
        // Check if old equivalent exists
        String old = convertNewToOld(name);
        if (old.equals(name)) {
            return; // already old attribute
        }
        // For textAlignment, check gravity
        if (name.equals(SdkConstants.ATTR_TEXT_ALIGNMENT)) {
            Element element = attribute.getOwnerElement();
            if (!element.hasAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_GRAVITY)
                    && !element.hasAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_LAYOUT_GRAVITY)) {
                context.report(...);
            }
            return;
        }
        // For other RTL attributes, check if old equivalent is present
        Element element = attribute.getOwnerElement();
        if (!element.hasAttributeNS(SdkConstants.ANDROID_URI, old)) {
            context.report(...);
        }
    }
}
